  "inlineSchema": "// This is your Prisma schema file for Timelines Costume Designers\n// MySQL on Hostinger\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ─── Users (Admin / Staff) ────────────────────────────────────────────────\nmodel User {\n  id            String     @id @default(cuid())\n  name          String\n  email         String     @unique\n  password      String\n  role          String     @default(\"staff\") // \"admin\" | \"staff\"\n  employeeRef   String? // employeeId ref (string)\n  plainPassword String?    @default(\"timelines123\")\n  isActive      Boolean    @default(true)\n  createdAt     DateTime   @default(now())\n  updatedAt     DateTime   @updatedAt\n  auditLogs     AuditLog[]\n}\n\n// ─── Customers ────────────────────────────────────────────────────────────\nmodel Customer {\n  customerId   String        @id // TC-YYYY-XXXX\n  name         String\n  phone        String\n  address      String        @default(\"\") @db.Text\n  email        String        @default(\"\")\n  notes        String        @default(\"\") @db.Text\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n  designOrders DesignOrder[]\n  payments     Payment[]\n}\n\n// ─── Employees ────────────────────────────────────────────────────────────\nmodel Employee {\n  employeeId   String        @id // EMP-XXXX\n  name         String\n  role         String // Tailor | Designer | Helper | Manager | Cutter | Other\n  phone        String        @default(\"\")\n  email        String        @default(\"\")\n  address      String        @default(\"\") @db.Text\n  joiningDate  DateTime      @default(now())\n  status       String        @default(\"active\") // active | inactive\n  notes        String        @default(\"\") @db.Text\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n  designOrders DesignOrder[]\n  salaries     Salary[]\n}\n\n// ─── Garment Templates ────────────────────────────────────────────────────\nmodel GarmentTemplate {\n  id          String   @id @default(cuid())\n  garmentType String   @unique\n  fields      Json // Array of {name, label, unit, required, order}\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// ─── Design Orders ────────────────────────────────────────────────────────\nmodel DesignOrder {\n  orderId             String    @id // ORD-XXXX\n  customerId          String\n  customer            Customer  @relation(fields: [customerId], references: [customerId])\n  garmentType         String\n  measurements        Json      @default(\"{}\") // {fieldName: value}\n  fabricNotes         String    @default(\"\") @db.Text\n  specialInstructions String    @default(\"\") @db.Text\n  assignedTailorId    String?\n  tailor              Employee? @relation(fields: [assignedTailorId], references: [employeeId])\n  status              String    @default(\"Pending\") // Pending | In Progress | Ready | Delivered\n  designSketchUrl     String?\n  designSketchJSON    String?   @db.LongText\n  orderDate           DateTime  @default(now())\n  deliveryDate        DateTime?\n  createdById         String?\n  createdAt           DateTime  @default(now())\n  updatedAt           DateTime  @updatedAt\n  payments            Payment[]\n}\n\n// ─── Salary ───────────────────────────────────────────────────────────────\nmodel Salary {\n  id             String   @id @default(cuid())\n  employeeId     String\n  employee       Employee @relation(fields: [employeeId], references: [employeeId])\n  month          Int // 1–12\n  year           Int\n  baseSalary     Float    @default(0)\n  advances       Float    @default(0)\n  deductions     Float    @default(0)\n  bonus          Float    @default(0)\n  netPaid        Float    @default(0)\n  paidStatus     String   @default(\"unpaid\") // unpaid | partial | paid\n  paymentHistory Json     @default(\"[]\") // [{amount, note, paidAt}]\n  notes          String   @default(\"\") @db.Text\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  @@unique([employeeId, month, year])\n}\n\n// ─── Audit Log ────────────────────────────────────────────────────────────\nmodel AuditLog {\n  id            String   @id @default(cuid())\n  recordType    String // Customer | Employee | DesignOrder | Salary | GarmentTemplate\n  recordId      String\n  action        String // create | update | delete\n  changedById   String\n  changedBy     User     @relation(fields: [changedById], references: [id])\n  changedByName String?\n  changes       Json     @default(\"[]\") // [{field, oldValue, newValue}]\n  snapshot      Json?\n  timestamp     DateTime @default(now())\n\n  @@index([recordType, recordId])\n  @@index([timestamp])\n}\n\n// ─── Inventory & Purchases ────────────────────────────────────────────────\nmodel InventoryItem {\n  id            String     @id @default(cuid())\n  name          String\n  category      String     @default(\"Raw Material\") // e.g., Thread, Fabric, Buttons\n  quantity      Float      @default(0)\n  unit          String     @default(\"pcs\") // e.g., meters, spools, pcs\n  minStockLevel Float      @default(0)\n  purchases     Purchase[]\n  createdAt     DateTime   @default(now())\n  updatedAt     DateTime   @updatedAt\n}\n\nmodel Purchase {\n  id           String        @id @default(cuid())\n  itemId       String\n  item         InventoryItem @relation(fields: [itemId], references: [id])\n  quantity     Float\n  totalCost    Float\n  supplier     String        @default(\"\")\n  purchaseDate DateTime      @default(now())\n  createdAt    DateTime      @default(now())\n  updatedAt    DateTime      @updatedAt\n}\n\n// ─── Services ─────────────────────────────────────────────────────────────\nmodel Service {\n  id          String   @id @default(cuid())\n  name        String\n  description String   @default(\"\")\n  basePrice   Float\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n}\n\n// ─── Customer Payments ────────────────────────────────────────────────────\nmodel Payment {\n  id            String       @id @default(cuid())\n  customerId    String\n  customer      Customer     @relation(fields: [customerId], references: [customerId])\n  orderId       String?\n  order         DesignOrder? @relation(fields: [orderId], references: [orderId])\n  amount        Float\n  paymentDate   DateTime     @default(now())\n  paymentMethod String       @default(\"Cash\") // Cash, UPI, Card, Transfer\n  status        String       @default(\"Completed\") // Pending, Completed\n  notes         String       @default(\"\")\n  createdAt     DateTime     @default(now())\n  updatedAt     DateTime     @updatedAt\n}\n",
